6.1 Data importation
What would have happened if we didn’t have the TK BIS data ?
Code
Levels_time_points &lt;- c(as.character(seq(1,3,1)), "3b", as.character(seq(4,7,1)), "7b", as.character(seq(8,14,1)), "14b", as.character(seq(15,42,1)))

df_TK_IMD &lt;- f_read_data_TK("IMD") %&gt;%
  mutate(across(where(is.numeric), ~ na_if(.x, -1))) |&gt; 
  filter(Experiment != "TKBIS")


df_TK_IMD &lt;- df_TK_IMD |&gt; 
  mutate(
    Time = t,
    CiEPX = C_worm_EPX,
    CiIMD = C_worm_IMD,
    Weight = Weight_nog,
    Time_point_f = as.factor(Time_point)
  ) |&gt; 
  dplyr::select(Time, CiEPX, CiIMD, Weight, w, Molecule, ID, expo, Time_point_f, Nb_rep, Experiment) |&gt; 
  mutate(
    CiEPX = na_if(CiEPX, -1),
    CiIMD = na_if(CiIMD, -1)
    )|&gt; 
  mutate(
    Time_point_f = fct_relevel(Time_point_f, Levels_time_points)
  )

df_TK_IMD_mean &lt;- df_TK_IMD |&gt; 
  dplyr::select(-ID) |&gt; 
  group_by(Time) |&gt; 
  summarise(
    CiEPX = exp(mean(log(CiEPX[CiEPX &gt; 0]), na.rm = TRUE)),
    CiIMD = exp(mean(log(CiIMD[CiIMD &gt; 0]), na.rm = TRUE)),
    Weight = mean(Weight, na.rm = TRUE),
    w = mean(w, na.rm = TRUE),
    expo = mean(expo),
    .groups = "drop"
  ) |&gt; 
  mutate(Molecule = "IMD")

